<?php
namespace App\Http\Controllers\Admin;
use App\Http\Controllers\Controller; use App\Models\Order; use Illuminate\Http\Request; use Inertia\Inertia;
class OrderController extends Controller { public function index(Request $r){$q=Order::with('items')->latest();if($r->filled('status'))$q->where('status',$r->status);if($r->filled('search'))$q->where(function($x)use($r){$x->where('order_number','like','%'.$r->search.'%')->orWhere('customer_name','like','%'.$r->search.'%')->orWhere('phone','like','%'.$r->search.'%');});return Inertia::render('Admin/Orders',['orders'=>$q->paginate(20)->withQueryString(),'filters'=>$r->only(['status','search'])]);} public function show(Order $order){return Inertia::render('Admin/OrderShow',['order'=>$order->load('items')]);} public function updateStatus(Request $r,Order $order){$r->validate(['status'=>'required|in:pending,confirmed,preparing,out_for_delivery,delivered,cancelled']);$order->update(['status'=>$r->status]);return back();} }
